      const clientX = moveEvent.touches ? moveEvent.touches[0].clientX : (moveEvent.clientX || 0);
      const clientY = moveEvent.touches ? moveEvent.touches[0].clientY : (moveEvent.clientY || 0);

      let x = ((clientX - rect.left) / rect.width) * 100;
