                <div className="absolute bottom-2 left-2 text-rose-300 text-3xl"><i className="fas fa-seedling -rotate-135"></i></div>
                <div className="absolute top-0 left-0 p-4"><i className="fas fa-spa text-rose-100 text-4xl"></i></div>
