        ),
        containerStyle: { backgroundColor: '#fffcfc' } 
    },
    { 
        id: 'math_board', 
        name: 'سبورة الرياضيات', 
        previewColor: '#1a202c', 
        render: () => (
            <>
                <div className="absolute top-4 left-4 text-white/10 text-4xl font-serif">cos θ</div>
                <div className="absolute bottom-4 right-4 text-white/10 text-4xl font-serif">Σ x²</div>
                <div className="absolute top-4 right-4 text-white/10 text-4xl font-serif">a + b = c</div>
                <div className="absolute inset-4 border border-white/20 border-dashed"></div>
            </>
        ), 
        containerStyle: { backgroundColor: '#2d3748' },
        defaultColor: '#ffffff'
    },
    { 
        id: 'academic_grid', 
        name: 'دفتر مربعات', 
        previewColor: '#f7fafc', 
        render: () => (
            <>
                <div className="absolute inset-0" style={{ backgroundImage: 'radial-gradient(#cbd5e0 1px, transparent 0)', backgroundSize: '20px 20px' }}></div>
                <div className="absolute top-2 left-2 text-blue-400 text-2xl"><i className="fas fa-paperclip"></i></div>
                <div className="absolute bottom-4 right-4 text-orange-300 text-3xl"><i className="fas fa-pencil-alt"></i></div>
                <div className="absolute inset-2 border-2 border-blue-100 rounded"></div>
            </>
        ),
        containerStyle: { backgroundColor: 'white' }
    },
    { 
        id: 'official_blue', 
        name: 'رسمي أزرق', 
        previewColor: '#ebf8ff', 
        render: () => (
            <>
                <div className="absolute inset-2 border-2 border-blue-900"></div>
                <div className="absolute inset-4 border-4 border-double border-blue-700"></div>
                <div className="absolute top-0 right-0 p-2 text-blue-900 text-xl"><i className="fas fa-certificate"></i></div>
                <div className="absolute bottom-0 left-0 p-2 text-blue-900 text-xl"><i className="fas fa-certificate"></i></div>
