        district: 'مكتب التربية والتعليم بمديرية ............',
        school: 'مدرسة: ........................................',
        subject: 'المادة: ........................................',
        grade: 'الصف: ........................................',
        semester: 'الفصل الدراسي الثاني',
        year: '1447هـ / 2025 - 2026م',
        teacherName: '',
        supervisorName: '',
        schoolAdminName: ''
    });

    const [eagleImage, setEagleImage] = useState<string>('https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Emblem_of_Yemen.svg/200px-Emblem_of_Yemen.svg.png');
    const [secondaryLogo, setSecondaryLogo] = useState<string | null>(null);
    const [isExporting, setIsExporting] = useState(false);

    const secondaryLogoRef = useRef<HTMLInputElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    // --- Initialization ---
    useEffect(() => {
        // Create initial 5 rows
        const initialRows = Array.from({ length: 5 }).map((_, i) => createEmptyRow());
        setRows(initialRows);
    }, []);

    const createEmptyRow = (): SemesterRow => ({
        id: Math.random().toString(36).substr(2, 9),
        hijriDate: '',
        gregorianDate: '',
        periodCount: '1',
        lessonTitle: '',
        objectives: '',
        teachingMethods: '',
        educationalAids: '',
        activitiesIn: '',
        activitiesOut: '',
        values: '',
        evaluation: '',
        notes: ''
