    // --- Actions ---
    const addRow = () => setRows(prev => [...prev, createEmptyRow()]);
    const removeRow = (id: string) => setRows(prev => prev.filter(r => r.id !== id));

    const handleMetaChange = (field: keyof HeaderMeta, value: string) => {
        setMeta(prev => ({ ...prev, [field]: value }));
    };

    const handleRowChange = (id: string, field: keyof SemesterRow, value: string) => {
        setRows(prev => prev.map(r => r.id === id ? { ...r, [field]: value } : r));
    };

    const generateRowAI = async (id: string) => {
        const row = rows.find(r => r.id === id);
        if (!row || !row.lessonTitle.trim()) {
            alert('الرجاء إدخال عنوان الدرس أولاً ليقوم الذكاء الاصطناعي بتحليله.');
            return;
        }

        setRows(prev => prev.map(r => r.id === id ? { ...r, isGenerating: true } : r));

        try {
            const result = await generateSemesterRowContent(row.lessonTitle, meta.subject);
            setRows(prev => prev.map(r => r.id === id ? { 
                ...r, 
                objectives: result.objectives,
                teachingMethods: result.methods,
                educationalAids: result.aids,
                activitiesIn: result.activities,
                values: result.values,
                evaluation: result.evaluation,
                isGenerating: false 
            } : r));
        } catch (e) {
            alert('فشل في توليد المحتوى. يرجى المحاولة لاحقاً.');
            setRows(prev => prev.map(r => r.id === id ? { ...r, isGenerating: false } : r));
        }
    };

    const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (ev) => {
                if (ev.target?.result) setSecondaryLogo(ev.target.result as string);
            };
            reader.readAsDataURL(file);
        }
    };

    // --- Export Logic ---
    const exportPDF = async () => {
        setIsExporting(true);
        const element = document.getElementById('semester-plan-a4');
        if (!element) return;

        try {
            await Promise.race([document.fonts.ready, new Promise(resolve => setTimeout(resolve, 500))]);

            const canvas = await html2canvas(element, {
                scale: 2,
                useCORS: true,
                backgroundColor: '#ffffff'
            });

            const imgData = canvas.toDataURL('image/jpeg', 1.0);
            const pdf = new jspdf.jsPDF('l', 'mm', 'a4'); // Landscape
            const pdfWidth = pdf.internal.pageSize.getWidth();
            const pdfHeight = (canvas.height * pdfWidth) / canvas.width;

            pdf.addImage(imgData, 'JPEG', 0, 0, pdfWidth, pdfHeight);
            pdf.save('semester_plan.pdf');
        } catch (e) {
            console.error(e);
        } finally {
            setIsExporting(false);
