                            <p className="border-b border-gray-200"><input className="w-full bg-transparent outline-none" value={meta.school} onChange={e => handleMetaChange('school', e.target.value)} /></p>
                            <p className="border-b border-gray-200"><input className="w-full bg-transparent outline-none" value={meta.grade} onChange={e => handleMetaChange('grade', e.target.value)} /></p>
