        بيانات الاختبار:
        المادة: ${config.subject}
        الصف: ${config.grade}
        توزيع الأسئلة المطلوب بدقة: ${distributionInstructions}
        شروط خاصة: ${config.customInstructions || "لا يوجد"}
        الدرجة الكلية: ${config.totalMarks}
        هيكل JSON المطلوب:
        {
            "q1": { "title": "...", "content": "...", "subQuestions": ["..."] },
            ...
            "gradingTable": { "q1": 10, ... "total": 50 }
        }
        `;
        const response = await client.models.generateContent({
            model: "gemini-2.5-flash",
            contents: prompt,
            config: {
                responseMimeType: 'application/json'
            }
        });
        return JSON.parse(response.text);
    } catch (error) {
        console.error("Error generating structured exam:", error);
        throw error;
    }
};

import React, { useState, useRef, useEffect } from 'react';
import ToolHeader from '../ToolHeader';
import { generateBulkSemesterContent } from '../../services/geminiService';
import ActionButtons from '../ActionButtons';

// Declare libraries
declare const jspdf: any;
declare const html2canvas: any;

interface SemesterRow {
    id: string;
    hijriDate: string;
    gregorianDate: string;
    periodCount: string;
    lessonTitle: string;
    objectives: string;
    teachingMethods: string;
    educationalAids: string;
    activitiesIn: string;
    activitiesOut: string;
    values: string;
    evaluation: string;
    notes: string;
}

interface HeaderMeta {
    ministry: string;
    office: string;
    district: string;
    school: string;
    subject: string;
    grade: string;
    semester: string;
    year: string;
    startDate: string;
    teacherName: string;
    supervisorName: string;
    schoolAdminName: string;
}

const ROWS_PER_PAGE = 8; // Adjust based on landscape A4 height

const SemesterPlanner: React.FC<{ onBack: () => void }> = ({ onBack }) => {
    // --- State ---
    const [rows, setRows] = useState<SemesterRow[]>([]);
    const [meta, setMeta] = useState<HeaderMeta>({
        ministry: 'وزارة التربية والتعليم والبحث العلمي',
        office: 'مكتب التربية والتعليم بمحافظة ............',
        district: 'مكتب التربية والتعليم بمديرية ............',
        school: 'مدرسة: ........................................',
        subject: 'المادة: ........................................',
        grade: 'الصف: ........................................',
        semester: 'الفصل الدراسي الثاني',
        year: '1447هـ / 2025 - 2026م',
        startDate: new Date().toISOString().split('T')[0],
        teacherName: '',
        supervisorName: '',
        schoolAdminName: ''
    });

    const [wizardLessons, setWizardLessons] = useState<{title: string, count: string}[]>([{title: '', count: '1'}]);
    const [showWizard, setShowWizard] = useState(false);
    const [isBulkGenerating, setIsBulkGenerating] = useState(false);
    const [isExporting, setIsExporting] = useState(false);
    const [secondaryLogo, setSecondaryLogo] = useState<string | null>(null);

    const eagleImage = 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Emblem_of_Yemen.svg/200px-Emblem_of_Yemen.svg.png';
    const secondaryLogoRef = useRef<HTMLInputElement>(null);

    // --- Helpers ---
    const createEmptyRow = (): SemesterRow => ({
        id: Math.random().toString(36).substr(2, 9),
        hijriDate: '', gregorianDate: '', periodCount: '1', lessonTitle: '',
        objectives: '', teachingMethods: '', educationalAids: '', activitiesIn: '', activitiesOut: '', values: '', evaluation: '', notes: ''
    });

    // Simple Hijri approximation (Teacher tools usually accept manual tweak)
    const getHijriDate = (gDate: string) => {
        if(!gDate) return '';
        try {
            return new Intl.DateTimeFormat('ar-SA-u-ca-islamic-uma', {day:'numeric', month:'long', year:'numeric'}).format(new Date(gDate));
        } catch(e) { return ''; }
    };

    // --- Wizard Actions ---
    const addWizardLesson = () => setWizardLessons([...wizardLessons, {title: '', count: '1'}]);

    const updateWizardLesson = (index: number, field: 'title' | 'count', value: string) => {
        const newL = [...wizardLessons];
        newL[index][field] = value;
        setWizardLessons(newL);
    };

    const handleBulkGenerate = async () => {
        const validLessons = wizardLessons.filter(l => l.title.trim() !== '');
        if (validLessons.length === 0) {
            alert('الرجاء إدخال عناوين الدروس أولاً.');
            return;
        }

        setIsBulkGenerating(true);
        setShowWizard(false);

        try {
            const aiData = await generateBulkSemesterContent(validLessons, meta.subject);

            // Calculate dates (Sat-Wed cycle)
            let currentDate = new Date(meta.startDate);
            const finalRows: SemesterRow[] = validLessons.map((l, idx) => {
                // Find next school day
                while (currentDate.getDay() === 4 || currentDate.getDay() === 5) { // 4=Thu, 5=Fri
                    currentDate.setDate(currentDate.getDate() + 1);
                }

                const gStr = currentDate.toISOString().split('T')[0];
                const hStr = getHijriDate(gStr);

                const lessonAi = aiData[idx] || {};

                // Advance date for next lesson
                currentDate.setDate(currentDate.getDate() + 1);

                return {
                    id: Math.random().toString(36).substr(2, 9),
                    gregorianDate: gStr,
                    hijriDate: hStr,
                    periodCount: l.count,
                    lessonTitle: l.title,
                    objectives: lessonAi.objectives || '',
                    teachingMethods: lessonAi.methods || '',
                    educationalAids: lessonAi.aids || '',
                    activitiesIn: lessonAi.activitiesIn || '',
                    activitiesOut: lessonAi.activitiesOut || '',
                    values: lessonAi.values || '',
                    evaluation: lessonAi.evaluation || '',
                    notes: ''
                };
            });

            setRows(finalRows);
        } catch (e) {
            alert('حدث خطأ أثناء التوليد. يرجى المحاولة مرة أخرى.');
        } finally {
            setIsBulkGenerating(false);
        }
    };

    // --- Table Actions ---
    const addRow = () => setRows([...rows, createEmptyRow()]);
    const removeRow = (id: string) => setRows(rows.filter(r => r.id !== id));
    const handleRowChange = (id: string, field: keyof SemesterRow, value: string) => {
        setRows(rows.map(r => r.id === id ? { ...r, [field]: value } : r));
    };

    // --- Export ---
    const handleExportPDF = async () => {
        setIsExporting(true);
        const pdf = new jspdf.jsPDF('l', 'mm', 'a4');
        const pages = document.querySelectorAll('.semester-plan-page');

        try {
            for (let i = 0; i < pages.length; i++) {
                const canvas = await html2canvas(pages[i] as HTMLElement, {
                    scale: 2,
                    useCORS: true,
                    backgroundColor: '#ffffff',
                    logging: false
                });
                const imgData = canvas.toDataURL('image/jpeg', 0.95);
                const pdfWidth = pdf.internal.pageSize.getWidth();
                const pdfHeight = (canvas.height * pdfWidth) / canvas.width;

                if (i > 0) pdf.addPage();
                pdf.addImage(imgData, 'JPEG', 0, 0, pdfWidth, pdfHeight);
            }
            pdf.save('semester_plan.pdf');
        } catch (e) {
            console.error(e);
        } finally {
            setIsExporting(false);
        }
    };

    // --- Pagination Logic ---
    const paginatedRows = [];
    for (let i = 0; i < rows.length; i += ROWS_PER_PAGE) {
        paginatedRows.push(rows.slice(i, i + ROWS_PER_PAGE));
    }
    if (paginatedRows.length === 0) paginatedRows.push([]); // Ensure at least one page

    return (
        <div className="pb-20">
            <ToolHeader title="خطة توزيع المنهج الفصلية" onBack={onBack} />

            {/* Control Panel */}
            <div className="no-print neumorphic-outset p-6 mb-8 flex flex-wrap gap-4 items-center justify-center sticky top-20 z-40 bg-white/80 backdrop-blur-md">
                <button onClick={() => setShowWizard(true)} className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold hover:scale-105 transition-transform flex items-center gap-2">
                    <i className="fas fa-magic"></i> إنشاء الخطة إلكترونياً
                </button>
                <button onClick={addRow} className="bg-emerald-600 text-white px-6 py-2 rounded-xl font-bold hover:scale-105 transition-transform">
                    <i className="fas fa-plus ml-2"></i> إضافة صف يدوي
                </button>
                <button onClick={handleExportPDF} disabled={isExporting || rows.length === 0} className="bg-red-600 text-white px-6 py-2 rounded-xl font-bold hover:scale-105 transition-transform flex items-center gap-2">
                    {isExporting ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-file-pdf"></i>} تصدير PDF
                </button>
            </div>

            {/* AI Progress */}
            {isBulkGenerating && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 backdrop-blur-sm">
                    <div className="bg-white p-8 rounded-2xl shadow-2xl flex flex-col items-center max-w-sm text-center">
                        <div className="w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mb-4"></div>
                        <h4 className="text-xl font-bold text-gray-800 mb-2">جاري إنشاء الخطة...</h4>
                        <p className="text-sm text-gray-500">يقوم الذكاء الاصطناعي الآن بتحليل الدروس وتوليد المحتوى التربوي المناسب.</p>
                    </div>
                </div>
            )}

            {/* Wizard Modal */}
            {showWizard && (
                <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/50 overflow-y-auto">
                    <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl p-6 max-h-[90vh] overflow-y-auto animate-scaleIn">
                        <div className="flex justify-between items-center mb-6 border-b pb-4">
                            <h3 className="text-2xl font-bold text-indigo-800">معالج إعداد الخطة الفصلية</h3>
                            <button onClick={() => setShowWizard(false)} className="text-gray-400 hover:text-red-500"><i className="fas fa-times text-xl"></i></button>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-8">
                            <div className="space-y-3">
                                <input type="text" placeholder="الوزارة" value={meta.ministry} onChange={e => setMeta({...meta, ministry: e.target.value})} className="w-full p-2 border rounded bg-gray-50" />
                                <input type="text" placeholder="مكتب التربية بـ..." value={meta.office} onChange={e => setMeta({...meta, office: e.target.value})} className="w-full p-2 border rounded bg-gray-50" />
                                <input type="text" placeholder="مديرية..." value={meta.district} onChange={e => setMeta({...meta, district: e.target.value})} className="w-full p-2 border rounded bg-gray-50" />
                                <input type="text" placeholder="اسم المدرسة" value={meta.school} onChange={e => setMeta({...meta, school: e.target.value})} className="w-full p-2 border rounded bg-gray-50" />
                            </div>
                            <div className="space-y-3">
                                <input type="text" placeholder="المادة" value={meta.subject} onChange={e => setMeta({...meta, subject: e.target.value})} className="w-full p-2 border rounded bg-gray-50" />
