                                <input type="date" value={meta.startDate} onChange={e => setMeta({...meta, startDate: e.target.value})} className="w-full p-2 border border-blue-200 rounded text-center mb-2 font-bold" />
                                <div className="mt-auto p-2 bg-white rounded border text-center text-xs text-blue-600">سيتم حساب التاريخ الهجري تلقائياً مع مراعاة أيام الإجازة.</div>
                            </div>
                        </div>

                        <div className="mb-6">
                            <div className="flex justify-between items-center mb-2">
                                <h4 className="font-bold text-gray-700">المحتوى وعناوين الدروس:</h4>
                                <button onClick={addWizardLesson} className="text-sm bg-emerald-100 text-emerald-700 px-3 py-1 rounded-full font-bold hover:bg-emerald-200"><i className="fas fa-plus ml-1"></i> إضافة درس</button>
                            </div>
                            <div className="space-y-2 max-h-[300px] overflow-y-auto pr-2 border rounded-lg p-2 bg-gray-50 shadow-inner">
                                {wizardLessons.map((l, i) => (
