                                        <div className="flex items-center gap-1">
                                            <span className="text-xs text-gray-500">حصص:</span>
                                            <input type="number" min="1" value={l.count} onChange={e => updateWizardLesson(i, 'count', e.target.value)} className="w-12 p-1 border rounded text-center font-bold" />
