                                    </div>
                                ))}
                            </div>
                        </div>

                        <button onClick={handleBulkGenerate} className="w-full bg-indigo-600 text-white py-4 rounded-xl font-bold text-xl shadow-lg hover:bg-indigo-700 transition-colors">إنشاء الخطة الفصلية إلكترونياً</button>
