            {/* Pagination View */}
            <div className="flex flex-col gap-12 items-center overflow-x-auto p-4">
                {paginatedRows.map((pageRows, pageIdx) => (
                    <div 
                        key={pageIdx}
                        className="semester-plan-page bg-white text-black shadow-2xl p-10 min-h-[210mm] w-[297mm] border border-gray-300 relative flex flex-col"
                        style={{ direction: 'rtl', textAlign: 'right', fontFamily: "'Times New Roman', serif" }}
                    >
                        {/* Header Page Layout */}
                        <div className="flex justify-between items-start mb-6">
                            {/* RIGHT: Republic Info */}
                            <div className="w-[30%] flex flex-col gap-1 font-bold text-[10pt] leading-tight text-right text-black">
                                <p>الجمهورية اليمنية</p>
                                <p className="border-b border-black/10"><input className="w-full bg-transparent outline-none" value={meta.ministry} onChange={e => setMeta({...meta, ministry: e.target.value})} /></p>
                                <p className="border-b border-black/10"><input className="w-full bg-transparent outline-none" value={meta.office} onChange={e => setMeta({...meta, office: e.target.value})} /></p>
                                <p className="border-b border-black/10"><input className="w-full bg-transparent outline-none" value={meta.district} onChange={e => setMeta({...meta, district: e.target.value})} /></p>
                                <p className="border-b border-black/10"><input className="w-full bg-transparent outline-none" value={meta.school} onChange={e => setMeta({...meta, school: e.target.value})} /></p>
                            </div>

                            {/* CENTER: Logos & Dynamic Title */}
                            <div className="w-[40%] flex flex-col items-center gap-3">
