                                            onChange={e => setMeta({...meta, year: e.target.value})}
                                            onInput={(e) => { e.currentTarget.style.height = 'auto'; e.currentTarget.style.height = e.currentTarget.scrollHeight + 'px'; }}
                                        />
                                    </div>
                                </div>
                            </div>

                            {/* LEFT: Grade / Semester info */}
                            <div className="w-[30%] flex flex-col gap-1 font-bold text-[10pt] leading-tight text-left items-end text-black">
                                <p className="border-b border-black/10 text-left w-full"><input className="w-full bg-transparent outline-none text-left" value={meta.grade} onChange={e => setMeta({...meta, grade: e.target.value})} /></p>
                                <p className="border-b border-black/10 text-left w-full"><input className="w-full bg-transparent outline-none text-left" value={`الفصل الدراسي: ${meta.semester}`} onChange={e => setMeta({...meta, semester: e.target.value})} /></p>
                                <p className="text-xs text-gray-500 mt-4 opacity-50">صفحة {pageIdx + 1} من {paginatedRows.length}</p>
                            </div>
                        </div>

                        {/* Master Table */}
                        <div className="flex-grow">
                            <table className="w-full border-collapse border-2 border-black text-[10pt]">
                                <thead className="bg-gray-100 font-black text-center">
                                    <tr>
                                        <th className="border border-black p-2 w-[110px]" colSpan={2}>التاريخ</th>
                                        <th className="border border-black p-2 w-[40px]" rowSpan={2}>عدد</th>
                                        <th className="border border-black p-2 w-[140px]" rowSpan={2}>المحتوى (عناوين الدروس)</th>
                                        <th className="border border-black p-2" rowSpan={2}>الأهداف التعليمية</th>
                                        <th className="border border-black p-2" rowSpan={2}>طرائق التدريس</th>
                                        <th className="border border-black p-2" rowSpan={2}>الوسائل</th>
                                        <th className="border border-black p-2" colSpan={2}>الأنشطة</th>
                                        <th className="border border-black p-2" rowSpan={2}>القيم</th>
                                        <th className="border border-black p-2" rowSpan={2}>أساليب التقويم</th>
                                        <th className="border border-black p-2 w-[70px]" rowSpan={2}>ملحوظات</th>
                                    </tr>
                                    <tr className="bg-gray-50 font-bold text-[8pt]">
                                        <th className="border border-black p-1">هجري</th>
                                        <th className="border border-black p-1">ميلادي</th>
                                        <th className="border border-black p-1">الصفية</th>
                                        <th className="border border-black p-1">اللاصفية</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {pageRows.map((row, idx) => (
                                        <tr key={row.id} className="text-[13px] text-black hover:bg-gray-50/50">
                                            <td className="border border-black p-1 text-center"><input type="text" value={row.hijriDate} onChange={e => handleRowChange(row.id, 'hijriDate', e.target.value)} className="w-full bg-transparent text-center outline-none text-[10px]" /></td>
                                            <td className="border border-black p-1 text-center"><input type="date" value={row.gregorianDate} onChange={e => handleRowChange(row.id, 'gregorianDate', e.target.value)} className="w-full bg-transparent text-center outline-none text-[10px]" /></td>
                                            <td className="border border-black p-1 text-center"><input type="text" value={row.periodCount} onChange={e => handleRowChange(row.id, 'periodCount', e.target.value)} className="w-full bg-transparent text-center outline-none" /></td>
                                            <td className="border border-black p-1 font-bold"><div contentEditable onBlur={e => handleRowChange(row.id, 'lessonTitle', e.currentTarget.innerText)} className="min-h-[30px] outline-none" dangerouslySetInnerHTML={{__html: row.lessonTitle}}></div></td>
                                            <td className="border border-black p-1 leading-tight"><div contentEditable onBlur={e => handleRowChange(row.id, 'objectives', e.currentTarget.innerText)} className="min-h-[30px] outline-none" dangerouslySetInnerHTML={{__html: row.objectives}}></div></td>
                                            <td className="border border-black p-1 leading-tight"><div contentEditable onBlur={e => handleRowChange(row.id, 'teachingMethods', e.currentTarget.innerText)} className="min-h-[30px] outline-none" dangerouslySetInnerHTML={{__html: row.teachingMethods}}></div></td>
                                            <td className="border border-black p-1 leading-tight"><div contentEditable onBlur={e => handleRowChange(row.id, 'educationalAids', e.currentTarget.innerText)} className="min-h-[30px] outline-none" dangerouslySetInnerHTML={{__html: row.educationalAids}}></div></td>
                                            <td className="border border-black p-1 leading-tight"><div contentEditable onBlur={e => handleRowChange(row.id, 'activitiesIn', e.currentTarget.innerText)} className="min-h-[30px] outline-none" dangerouslySetInnerHTML={{__html: row.activitiesIn}}></div></td>
                                            <td className="border border-black p-1 leading-tight"><div contentEditable onBlur={e => handleRowChange(row.id, 'activitiesOut', e.currentTarget.innerText)} className="min-h-[30px] outline-none" dangerouslySetInnerHTML={{__html: row.activitiesOut}}></div></td>
                                            <td className="border border-black p-1 leading-tight"><div contentEditable onBlur={e => handleRowChange(row.id, 'values', e.currentTarget.innerText)} className="min-h-[30px] outline-none" dangerouslySetInnerHTML={{__html: row.values}}></div></td>
                                            <td className="border border-black p-1 leading-tight"><div contentEditable onBlur={e => handleRowChange(row.id, 'evaluation', e.currentTarget.innerText)} className="min-h-[30px] outline-none" dangerouslySetInnerHTML={{__html: row.evaluation}}></div></td>
                                            <td className="border border-black p-1 leading-tight"><div contentEditable onBlur={e => handleRowChange(row.id, 'notes', e.currentTarget.innerText)} className="min-h-[30px] outline-none" dangerouslySetInnerHTML={{__html: row.notes}}></div></td>
                                        </tr>
                                    ))}
                                    {/* Empty rows to maintain page height if needed */}
                                    {pageRows.length < ROWS_PER_PAGE && Array.from({length: ROWS_PER_PAGE - pageRows.length}).map((_, i) => (
                                        <tr key={i} className="h-10"><td colSpan={12} className="border border-black bg-gray-50/20"></td></tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>

                        {/* Signatures at end of EVERY page */}
                        <div className="mt-8 grid grid-cols-3 gap-8 text-center font-bold text-sm border-t-2 border-black pt-4">
                            <div className="flex flex-col gap-2">
                                <p>اسم المعلم وتوقيعه:</p>
                                <input className="bg-transparent text-center border-b border-dotted border-black w-full outline-none" value={meta.teacherName} onChange={e => setMeta({...meta, teacherName: e.target.value})} placeholder="............................" />
                            </div>
                            <div className="flex flex-col gap-2">
                                <p>المشرف التربوي:</p>
                                <input className="bg-transparent text-center border-b border-dotted border-black w-full outline-none" value={meta.supervisorName} onChange={e => setMeta({...meta, supervisorName: e.target.value})} placeholder="............................" />
                            </div>
                            <div className="flex flex-col gap-2">
                                <p>إدارة المدرسة:</p>
                                <input className="bg-transparent text-center border-b border-dotted border-black w-full outline-none" value={meta.schoolAdminName} onChange={e => setMeta({...meta, schoolAdminName: e.target.value})} placeholder="............................" />
                            </div>
                        </div>
                    </div>
                ))}
            </div>

            {/* Floater Hint */}
            <div className="fixed bottom-6 right-6 no-print max-w-xs p-4 bg-primary text-white rounded-2xl shadow-2xl animate-bounce">
                <p className="text-xs font-bold text-center">
                    <i className="fas fa-lightbulb ml-1"></i> نصيحة: استخدم "معالج الإعداد" لإنشاء الخطة كاملة في دقيقة واحدة باستخدام الذكاء الاصطناعي!
                </p>
            </div>
        </div>
    );
};

export default SemesterPlanner;

import React, { useState, useRef, useEffect } from 'react';
import ToolHeader from '../ToolHeader';
import { generateBulkSemesterContent } from '../../services/geminiService';
import ActionButtons from '../ActionButtons';

// Declare libraries
declare const jspdf: any;
declare const html2canvas: any;

interface SemesterRow {
    id: string;
    hijriDate: string;
    gregorianDate: string;
    periodCount: string;
    lessonTitle: string;
    objectives: string;
    teachingMethods: string;
    educationalAids: string;
    activitiesIn: string;
    activitiesOut: string;
    values: string;
    evaluation: string;
    notes: string;
}

interface HeaderMeta {
    ministry: string;
    office: string;
    district: string;
    school: string;
    subject: string;
    grade: string;
    semester: string;
    year: string;
    startDate: string;
    teacherName: string;
    supervisorName: string;
    schoolAdminName: string;
}

// 6 to 8 rows usually fit perfectly on A4 Landscape with header/footer
const ROWS_PER_PAGE = 7; 

const SemesterPlanner: React.FC<{ onBack: () => void }> = ({ onBack }) => {
    // --- State ---
    const [rows, setRows] = useState<SemesterRow[]>([]);
    const [meta, setMeta] = useState<HeaderMeta>({
        ministry: 'وزارة التربية والتعليم والبحث العلمي',
        office: 'مكتب التربية والتعليم بـ',
        district: 'مكتب التربية والتعليم بمديرية',
        school: 'مدرسة',
        subject: 'اللغة العربية',
        grade: 'الثامن',
        semester: 'الثاني',
        year: '1447',
        startDate: new Date().toISOString().split('T')[0],
        teacherName: '',
        supervisorName: '',
        schoolAdminName: ''
    });

    const [wizardLessons, setWizardLessons] = useState<{title: string, count: string}[]>([{title: '', count: '1'}]);
    const [showWizard, setShowWizard] = useState(false);
    const [isBulkGenerating, setIsBulkGenerating] = useState(false);
    const [isExporting, setIsExporting] = useState(false);
    const [secondaryLogo, setSecondaryLogo] = useState<string | null>(null);

    const eagleImage = 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Emblem_of_Yemen.svg/200px-Emblem_of_Yemen.svg.png';
    const secondaryLogoRef = useRef<HTMLInputElement>(null);

    // --- Helpers ---
    const createEmptyRow = (): SemesterRow => ({
        id: Math.random().toString(36).substr(2, 9),
        hijriDate: '', gregorianDate: '', periodCount: '1', lessonTitle: '',
        objectives: '', teachingMethods: '', educationalAids: '', activitiesIn: '', activitiesOut: '', values: '', evaluation: '', notes: ''
    });

    const getHijriDate = (gDate: string) => {
        if(!gDate) return '';
        try {
            return new Intl.DateTimeFormat('ar-SA-u-ca-islamic-uma', {day:'numeric', month:'long', year:'numeric'}).format(new Date(gDate));
        } catch(e) { return ''; }
    };

    // --- Wizard Logic ---
    const updateWizardLesson = (index: number, field: 'title' | 'count', value: string) => {
        const newL = [...wizardLessons];
        newL[index][field] = value;

        // Auto-add new row if typing in the last one
        if (field === 'title' && index === newL.length - 1 && value.trim() !== '') {
            newL.push({title: '', count: '1'});
        }

        setWizardLessons(newL);
    };

    const removeWizardLesson = (index: number) => {
        if (wizardLessons.length > 1) {
            setWizardLessons(wizardLessons.filter((_, i) => i !== index));
        }
    };

    const handleBulkGenerate = async () => {
        const validLessons = wizardLessons.filter(l => l.title.trim() !== '');
        if (validLessons.length === 0) {
            alert('الرجاء إدخال عناوين الدروس أولاً.');
            return;
        }

        setIsBulkGenerating(true);
        setShowWizard(false);

        try {
            const aiData = await generateBulkSemesterContent(validLessons, meta.subject);
            let currentDate = new Date(meta.startDate);
            const finalRows: SemesterRow[] = validLessons.map((l, idx) => {
                while (currentDate.getDay() === 4 || currentDate.getDay() === 5) { 
                    currentDate.setDate(currentDate.getDate() + 1);
                }
                const gStr = currentDate.toISOString().split('T')[0];
                const hStr = getHijriDate(gStr);
                const lessonAi = aiData[idx] || {};
                currentDate.setDate(currentDate.getDate() + 1);

                return {
                    id: Math.random().toString(36).substr(2, 9),
                    gregorianDate: gStr,
                    hijriDate: hStr,
                    periodCount: l.count,
                    lessonTitle: l.title,
                    objectives: lessonAi.objectives || '',
                    teachingMethods: lessonAi.methods || '',
                    educationalAids: lessonAi.aids || '',
                    activitiesIn: lessonAi.activitiesIn || '',
                    activitiesOut: lessonAi.activitiesOut || '',
                    values: lessonAi.values || '',
                    evaluation: lessonAi.evaluation || '',
                    notes: ''
                };
            });
            setRows(finalRows);
        } catch (e) {
            alert('حدث خطأ أثناء التوليد. سيتم تعبئة الحقول الأساسية فقط.');
            const fallbackRows = validLessons.map(l => ({ ...createEmptyRow(), lessonTitle: l.title, periodCount: l.count }));
            setRows(fallbackRows);
        } finally {
            setIsBulkGenerating(false);
        }
    };

    const handleRowChange = (id: string, field: keyof SemesterRow, value: string) => {
        setRows(rows.map(r => r.id === id ? { ...r, [field]: value } : r));
    };

    const handleExportPDF = async () => {
        setIsExporting(true);
        const pdf = new jspdf.jsPDF('l', 'mm', 'a4');
        const pages = document.querySelectorAll('.semester-plan-page');

        try {
            await Promise.race([document.fonts.ready, new Promise(r => setTimeout(r, 1000))]);

            for (let i = 0; i < pages.length; i++) {
                const canvas = await html2canvas(pages[i] as HTMLElement, {
                    scale: 2.5, // High quality
                    useCORS: true,
                    backgroundColor: '#ffffff',
                    logging: false,
                    onclone: (clonedDoc) => {
                        // Ensure all inputs are readable in export by forcing their value display
                        const inputs = clonedDoc.querySelectorAll('input, textarea');
                        inputs.forEach((inp: any) => {
                           if (inp.style) inp.style.opacity = "1";
                        });
                    }
                });
                const imgData = canvas.toDataURL('image/jpeg', 0.98);
                const pdfWidth = pdf.internal.pageSize.getWidth();
                const pdfHeight = pdf.internal.pageSize.getHeight();

                if (i > 0) pdf.addPage();
                pdf.addImage(imgData, 'JPEG', 0, 0, pdfWidth, pdfHeight, undefined, 'FAST');
            }
            pdf.save('خطة_توزيع_المنهج.pdf');
        } catch (e) {
            console.error(e);
            alert("حدث خطأ أثناء التصدير.");
        } finally {
            setIsExporting(false);
        }
    };

    // --- Pagination Logic ---
    const paginatedRows = [];
    for (let i = 0; i < rows.length; i += ROWS_PER_PAGE) {
        paginatedRows.push(rows.slice(i, i + ROWS_PER_PAGE));
    }
    if (paginatedRows.length === 0) paginatedRows.push([]);

    return (
        <div className="pb-20">
            <ToolHeader title="خطة توزيع المنهج الفصلية" onBack={onBack} />

            <div className="no-print neumorphic-outset p-6 mb-8 flex flex-wrap gap-4 items-center justify-center sticky top-20 z-40 bg-white/90 backdrop-blur-md border border-indigo-100">
                <button onClick={() => setShowWizard(true)} className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold hover:scale-105 shadow-md flex items-center gap-2">
                    <i className="fas fa-magic"></i> معالج إعداد الخطة
                </button>
                <button onClick={() => setRows([...rows, createEmptyRow()])} className="bg-emerald-600 text-white px-6 py-2 rounded-xl font-bold hover:scale-105 shadow-md">
                    <i className="fas fa-plus ml-2"></i> إضافة صف يدوي
                </button>
                <button onClick={handleExportPDF} disabled={isExporting || rows.length === 0} className="bg-red-600 text-white px-6 py-2 rounded-xl font-bold hover:scale-105 shadow-md flex items-center gap-2">
                    {isExporting ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-file-pdf"></i>} تصدير PDF
                </button>
            </div>

            {isBulkGenerating && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/70 backdrop-blur-md">
                    <div className="bg-white p-10 rounded-3xl shadow-2xl flex flex-col items-center max-w-sm text-center">
                        <div className="w-20 h-20 border-8 border-indigo-600 border-t-transparent rounded-full animate-spin mb-6"></div>
                        <h4 className="text-2xl font-black text-gray-800 mb-2">جاري إنشاء الخطة...</h4>
                        <p className="text-gray-500 font-bold">يقوم الذكاء الاصطناعي بتنظيم المنهج وتوليد الأهداف والأنشطة.</p>
                    </div>
                </div>
            )}

            {showWizard && (
                <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm overflow-y-auto">
