import React, { useState, useRef, useEffect } from 'react';
import ToolHeader from '../ToolHeader';
import { generateBulkSemesterContent } from '../../services/geminiService';
import ActionButtons from '../ActionButtons';

// Declare libraries
declare const jspdf: any;
declare const html2canvas: any;

interface SemesterRow {
    id: string;
    hijriDate: string;
    gregorianDate: string;
    periodCount: string;
    lessonTitle: string;
    objectives: string;
    teachingMethods: string;
    educationalAids: string;
    activitiesIn: string;
    activitiesOut: string;
    values: string;
    evaluation: string;
    notes: string;
}

interface HeaderMeta {
    ministry: string;
    office: string;
    district: string;
    school: string;
    subject: string;
    grade: string;
    semester: string;
    year: string;
    startDate: string;
    teacherName: string;
    supervisorName: string;
    schoolAdminName: string;
}

// Adjusted for 13pt font size to fit A4 Landscape
const ROWS_PER_PAGE = 7; 

const SemesterPlanner: React.FC<{ onBack: () => void }> = ({ onBack }) => {
    // --- State ---
    const [rows, setRows] = useState<SemesterRow[]>([]);
    const [meta, setMeta] = useState<HeaderMeta>({
        ministry: 'وزارة التربية والتعليم والبحث العلمي',
        office: 'مكتب التربية والتعليم بـ',
        district: 'مكتب التربية والتعليم بمديرية',
        school: 'مدرسة',
        subject: 'اللغة العربية',
        grade: 'الثامن',
        semester: 'الثاني',
        year: '1447',
        startDate: new Date().toISOString().split('T')[0],
        teacherName: '',
        supervisorName: '',
        schoolAdminName: ''
    });

    const [wizardLessons, setWizardLessons] = useState<{title: string, count: string}[]>([{title: '', count: '1'}]);
    const [showWizard, setShowWizard] = useState(false);
    const [isBulkGenerating, setIsBulkGenerating] = useState(false);
    const [isExporting, setIsExporting] = useState(false);

    // Logos State
    const [secondaryLogo, setSecondaryLogo] = useState<string | null>(null);
    const [eagleImage, setEagleImage] = useState<string>('https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Emblem_of_Yemen.svg/200px-Emblem_of_Yemen.svg.png');

    const secondaryLogoRef = useRef<HTMLInputElement>(null);
    const eagleInputRef = useRef<HTMLInputElement>(null);

    // --- Helpers ---
    const createEmptyRow = (): SemesterRow => ({
        id: Math.random().toString(36).substr(2, 9),
        hijriDate: '', gregorianDate: '', periodCount: '1', lessonTitle: '',
        objectives: '', teachingMethods: '', educationalAids: '', activitiesIn: '', activitiesOut: '', values: '', evaluation: '', notes: ''
    });

    const getHijriDate = (gDate: string) => {
        if(!gDate) return '';
        try {
            return new Intl.DateTimeFormat('ar-SA-u-ca-islamic-uma', {day:'numeric', month:'long', year:'numeric'}).format(new Date(gDate));
        } catch(e) { return ''; }
    };

    // --- Wizard Logic ---
    const updateWizardLesson = (index: number, field: 'title' | 'count', value: string) => {
        const newL = [...wizardLessons];
        newL[index][field] = value;

        if (field === 'title' && index === newL.length - 1 && value.trim() !== '') {
            newL.push({title: '', count: '1'});
        }
        setWizardLessons(newL);
    };

    const removeWizardLesson = (index: number) => {
        if (wizardLessons.length > 1) {
            setWizardLessons(wizardLessons.filter((_, i) => i !== index));
        }
    };

    const handleBulkGenerate = async () => {
        const validLessons = wizardLessons.filter(l => l.title.trim() !== '');
        if (validLessons.length === 0) {
            alert('الرجاء إدخال عناوين الدروس أولاً.');
            return;
        }

        setIsBulkGenerating(true);
        setShowWizard(false);

        try {
            const aiData = await generateBulkSemesterContent(validLessons, meta.subject);
            let currentDate = new Date(meta.startDate);
            const finalRows: SemesterRow[] = validLessons.map((l, idx) => {
                while (currentDate.getDay() === 4 || currentDate.getDay() === 5) { 
                    currentDate.setDate(currentDate.getDate() + 1);
                }
                const gStr = currentDate.toISOString().split('T')[0];
                const hStr = getHijriDate(gStr);
                const lessonAi = aiData[idx] || {};
                currentDate.setDate(currentDate.getDate() + 1);

                return {
                    id: Math.random().toString(36).substr(2, 9),
                    gregorianDate: gStr,
                    hijriDate: hStr,
                    periodCount: l.count,
                    lessonTitle: l.title,
                    objectives: lessonAi.objectives || '',
                    teachingMethods: lessonAi.methods || '',
                    educationalAids: lessonAi.aids || '',
                    activitiesIn: lessonAi.activitiesIn || '',
                    activitiesOut: lessonAi.activitiesOut || '',
                    values: lessonAi.values || '',
                    evaluation: lessonAi.evaluation || '',
                    notes: ''
                };
            });
            setRows(finalRows);
        } catch (e) {
            alert('حدث خطأ أثناء التوليد.');
            const fallbackRows = validLessons.map(l => ({ ...createEmptyRow(), lessonTitle: l.title, periodCount: l.count }));
            setRows(fallbackRows);
        } finally {
            setIsBulkGenerating(false);
        }
    };

    const handleRowChange = (id: string, field: keyof SemesterRow, value: string) => {
        setRows(rows.map(r => r.id === id ? { ...r, [field]: value } : r));
    };

    const handleExportPDF = async () => {
        setIsExporting(true);
        const pdf = new jspdf.jsPDF('l', 'mm', 'a4');
        const pages = document.querySelectorAll('.semester-plan-page');

        try {
            await Promise.race([document.fonts.ready, new Promise(r => setTimeout(r, 1000))]);

            for (let i = 0; i < pages.length; i++) {
                const canvas = await html2canvas(pages[i] as HTMLElement, {
                    scale: 2.5,
                    useCORS: true,
                    backgroundColor: '#ffffff',
                    logging: false
                });
                const imgData = canvas.toDataURL('image/jpeg', 0.98);
                const pdfWidth = pdf.internal.pageSize.getWidth();
                const pdfHeight = pdf.internal.pageSize.getHeight();

                if (i > 0) pdf.addPage();
                pdf.addImage(imgData, 'JPEG', 0, 0, pdfWidth, pdfHeight, undefined, 'FAST');
            }
            pdf.save('خطة_توزيع_المنهج.pdf');
        } catch (e) {
            console.error(e);
            alert("حدث خطأ أثناء التصدير.");
        } finally {
            setIsExporting(false);
        }
    };

    // --- Pagination Logic ---
    const paginatedRows = [];
    for (let i = 0; i < rows.length; i += ROWS_PER_PAGE) {
        paginatedRows.push(rows.slice(i, i + ROWS_PER_PAGE));
    }
    if (paginatedRows.length === 0) paginatedRows.push([]);

    return (
        <div className="pb-20">
            <ToolHeader title="خطة توزيع المنهج الفصلية" onBack={onBack} />

