                </button>
                <button onClick={() => setRows([...rows, createEmptyRow()])} className="bg-emerald-600 text-white px-6 py-2 rounded-xl font-bold hover:scale-105 shadow-md">
                    <i className="fas fa-plus ml-2"></i> إضافة صف يدوي
                </button>
                <button onClick={handleExportPDF} disabled={isExporting || rows.length === 0} className="bg-red-600 text-white px-6 py-2 rounded-xl font-bold hover:scale-105 shadow-md flex items-center gap-2">
                    {isExporting ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-file-pdf"></i>} تصدير PDF
