                                            </tr>
                                        ))}
                                        {pageRows.length < ROWS_PER_PAGE && Array.from({length: ROWS_PER_PAGE - pageRows.length}).map((_, i) => (
                                            <tr key={i} className="h-16"><td colSpan={12} className="border border-black bg-gray-50/10"></td></tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>

                            {/* Signature Section */}
                            <div className="mt-8 grid grid-cols-3 gap-10 text-center font-bold text-sm border-t-2 border-black pt-5 text-black">
                                <div className="flex flex-col gap-4">
                                    <p className="font-black underline">معلم المادة</p>
                                    <div contentEditable onBlur={e => setMeta({...meta, teacherName: e.currentTarget.innerText})} className="bg-transparent text-center border-b border-dotted border-black w-full outline-none font-bold min-h-[25px]" dangerouslySetInnerHTML={{__html: meta.teacherName || '............................'}}></div>
