import React, { useState, useRef, useEffect } from 'react';
import ToolHeader from '../ToolHeader';
import { generateBulkSemesterContent } from '../../services/geminiService';
import ActionButtons from '../ActionButtons';

// Declare libraries
declare const jspdf: any;
declare const html2canvas: any;

interface SemesterRow {
    id: string;
    hijriDate: string;
    gregorianDate: string;
    periodCount: string;
    lessonTitle: string;
    objectives: string;
    teachingMethods: string;
    educationalAids: string;
    activitiesIn: string;
    activitiesOut: string;
    values: string;
    evaluation: string;
    notes: string;
}

interface HeaderMeta {
    ministry: string;
    office: string;
    district: string;
    school: string;
    subject: string;
    grade: string;
    semester: string;
    year: string;
    startDate: string;
    teacherName: string;
    supervisorName: string;
    schoolAdminName: string;
}

// 7 rows fit comfortably on A4 Landscape with 13pt font and headers/footers
const ROWS_PER_PAGE = 7; 

const SemesterPlanner: React.FC<{ onBack: () => void }> = ({ onBack }) => {
    // --- State ---
    const [rows, setRows] = useState<SemesterRow[]>([]);
    const [meta, setMeta] = useState<HeaderMeta>({
        ministry: 'وزارة التربية والتعليم والبحث العلمي',
        office: 'مكتب التربية والتعليم بـ',
        district: 'مكتب التربية والتعليم بمديرية',
        school: 'مدرسة',
        subject: 'اللغة العربية',
        grade: 'الثامن',
        semester: 'الثاني',
        year: '1447',
        startDate: '2026-01-01',
        teacherName: '',
        supervisorName: '',
        schoolAdminName: ''
    });

    const [wizardLessons, setWizardLessons] = useState<{title: string, count: string}[]>([{title: '', count: '1'}]);
    const [showWizard, setShowWizard] = useState(false);
    const [isBulkGenerating, setIsBulkGenerating] = useState(false);
    const [isExporting, setIsExporting] = useState(false);

    const [secondaryLogo, setSecondaryLogo] = useState<string | null>(null);
    const [eagleImage, setEagleImage] = useState<string>('https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Emblem_of_Yemen.svg/200px-Emblem_of_Yemen.svg.png');

    const secondaryLogoRef = useRef<HTMLInputElement>(null);
    const eagleInputRef = useRef<HTMLInputElement>(null);

    // --- Hijri Date Logic ---
    // Using Um-AlQura calendar via Intl for maximum accuracy
    const getHijriDate = (gDate: string) => {
        if(!gDate) return '';
        try {
            const date = new Date(gDate);
            // Hijri formatting to match: 12/ رجب/ 1447هـ
            const day = new Intl.DateTimeFormat('ar-SA-u-ca-islamic-uma', {day: 'numeric'}).format(date);
            const month = new Intl.DateTimeFormat('ar-SA-u-ca-islamic-uma', {month: 'long'}).format(date);
            const year = new Intl.DateTimeFormat('ar-SA-u-ca-islamic-uma', {year: 'numeric'}).format(date);
            return `${day}/ ${month}/ ${year}هـ`;
        } catch(e) { return ''; }
    };

    // --- Helpers ---
    const createEmptyRow = (): SemesterRow => ({
        id: Math.random().toString(36).substr(2, 9),
        hijriDate: '', gregorianDate: '', periodCount: '1', lessonTitle: '',
        objectives: '', teachingMethods: '', educationalAids: '', activitiesIn: '', activitiesOut: '', values: '', evaluation: '', notes: ''
    });

    // --- Wizard Logic ---
    const updateWizardLesson = (index: number, field: 'title' | 'count', value: string) => {
        const newL = [...wizardLessons];
        newL[index][field] = value;
        if (field === 'title' && index === newL.length - 1 && value.trim() !== '') {
            newL.push({title: '', count: '1'});
        }
        setWizardLessons(newL);
    };

    const removeWizardLesson = (index: number) => {
        if (wizardLessons.length > 1) {
            setWizardLessons(wizardLessons.filter((_, i) => i !== index));
        }
    };

    const handleBulkGenerate = async () => {
        const validLessons = wizardLessons.filter(l => l.title.trim() !== '');
        if (validLessons.length === 0) {
            alert('الرجاء إدخال عناوين الدروس أولاً.');
            return;
        }

        setIsBulkGenerating(true);
        setShowWizard(false);

        try {
            const aiData = await generateBulkSemesterContent(validLessons, meta.subject);
            let currentDate = new Date(meta.startDate);
            const finalRows: SemesterRow[] = validLessons.map((l, idx) => {
                // Skip Thu/Fri (Yemen School Days Sat-Wed)
                while (currentDate.getDay() === 4 || currentDate.getDay() === 5) { 
                    currentDate.setDate(currentDate.getDate() + 1);
                }
                const gStr = currentDate.toISOString().split('T')[0];
                const hStr = getHijriDate(gStr);
                const lessonAi = aiData[idx] || {};
                currentDate.setDate(currentDate.getDate() + 1);

                return {
                    id: Math.random().toString(36).substr(2, 9),
                    gregorianDate: gStr,
                    hijriDate: hStr,
                    periodCount: l.count,
                    lessonTitle: l.title,
                    objectives: lessonAi.objectives || '',
                    teachingMethods: lessonAi.methods || '',
                    educationalAids: lessonAi.aids || '',
                    activitiesIn: lessonAi.activitiesIn || '',
                    activitiesOut: lessonAi.activitiesOut || '',
                    values: lessonAi.values || '',
                    evaluation: lessonAi.evaluation || '',
                    notes: ''
                };
            });
            setRows(finalRows);
        } catch (e) {
            alert('حدث خطأ أثناء التوليد.');
            const fallbackRows = validLessons.map(l => ({ ...createEmptyRow(), lessonTitle: l.title, periodCount: l.count }));
            setRows(fallbackRows);
        } finally {
            setIsBulkGenerating(false);
        }
    };

    const handleRowChange = (id: string, field: keyof SemesterRow, value: string) => {
        setRows(rows.map(r => r.id === id ? { ...r, [field]: value } : r));
    };

    const handleExportPDF = async () => {
        setIsExporting(true);
        const pdf = new jspdf.jsPDF({
            orientation: 'landscape',
            unit: 'mm',
            format: 'a4',
            compress: true
        });

        const pages = document.querySelectorAll('.semester-plan-page');

        try {
            // Wait for all images and fonts to load
            await Promise.race([document.fonts.ready, new Promise(r => setTimeout(r, 1000))]);

            for (let i = 0; i < pages.length; i++) {
                const pageElement = pages[i] as HTMLElement;

                // Clone settings for high-quality capture
                const canvas = await html2canvas(pageElement, {
                    scale: 3, // Very high resolution
                    useCORS: true,
                    backgroundColor: '#ffffff',
                    logging: false,
                    width: pageElement.offsetWidth,
                    height: pageElement.offsetHeight,
                    onclone: (clonedDoc) => {
                        // Force black text for export quality
                        const allText = clonedDoc.querySelectorAll('*');
                        allText.forEach((el: any) => {
                            if (el.style) el.style.color = '#000000';
                        });
                    }
                });

                const imgData = canvas.toDataURL('image/jpeg', 1.0);
                const pdfWidth = pdf.internal.pageSize.getWidth();
                const pdfHeight = pdf.internal.pageSize.getHeight();

                if (i > 0) pdf.addPage();
                // Add image without stretching - fit to A4 exactly
                pdf.addImage(imgData, 'JPEG', 0, 0, pdfWidth, pdfHeight, undefined, 'NONE');
            }
            pdf.save(`خطة_توزيع_مقرر_${meta.subject}.pdf`);
        } catch (e) {
            console.error(e);
            alert("حدث خطأ أثناء التصدير. يرجى التأكد من استقرار المتصفح.");
        } finally {
            setIsExporting(false);
        }
    };

    // --- Pagination Logic ---
    const paginatedRows = [];
    for (let i = 0; i < rows.length; i += ROWS_PER_PAGE) {
        paginatedRows.push(rows.slice(i, i + ROWS_PER_PAGE));
    }
    if (paginatedRows.length === 0) paginatedRows.push([]);

    return (
        <div className="pb-20">
            <ToolHeader title="خطة توزيع المنهج الفصلية" onBack={onBack} />

            <div className="no-print neumorphic-outset p-6 mb-8 flex flex-wrap gap-4 items-center justify-center sticky top-20 z-40 bg-white/95 backdrop-blur-md border border-indigo-100 shadow-xl">
                <button onClick={() => setShowWizard(true)} className="bg-indigo-600 text-white px-8 py-3 rounded-2xl font-black hover:scale-105 shadow-lg flex items-center gap-2 transition-all">
                    <i className="fas fa-magic"></i> معالج إعداد الخطة الذكي
                </button>
                <button onClick={() => setRows([...rows, createEmptyRow()])} className="bg-emerald-600 text-white px-8 py-3 rounded-2xl font-black hover:scale-105 shadow-lg transition-all">
                    <i className="fas fa-plus ml-2"></i> إضافة صف يدوي
                </button>
                <button onClick={handleExportPDF} disabled={isExporting || rows.length === 0} className="bg-black text-white px-8 py-3 rounded-2xl font-black hover:scale-105 shadow-lg flex items-center gap-2 transition-all disabled:opacity-50">
                    {isExporting ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-file-pdf"></i>} تصدير PDF احترافي
                </button>
            </div>

            {isBulkGenerating && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-xl">
                    <div className="bg-white p-12 rounded-[2rem] shadow-2xl flex flex-col items-center max-w-md text-center border-4 border-indigo-100">
                        <div className="w-24 h-24 border-8 border-indigo-600 border-t-transparent rounded-full animate-spin mb-8"></div>
                        <h4 className="text-3xl font-black text-gray-900 mb-4">جاري تنظيم الخطة...</h4>
                        <p className="text-gray-600 font-bold leading-relaxed">نقوم الآن بحساب التواريخ بدقة وتوليد المحتوى التربوي المتوافق مع مادة {meta.subject}.</p>
                    </div>
                </div>
            )}

            {showWizard && (
                <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/70 backdrop-blur-md overflow-y-auto">
                    <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-5xl p-10 max-h-[90vh] overflow-y-auto animate-scaleIn border border-indigo-50">
                        <div className="flex justify-between items-center mb-10 border-b pb-6">
                            <h3 className="text-4xl font-black text-indigo-900">إعداد الخطة الفصلية</h3>
                            <button onClick={() => setShowWizard(false)} className="text-gray-400 hover:text-red-500 transition-colors"><i className="fas fa-times text-3xl"></i></button>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mb-10">
                            <div className="space-y-4">
                                <h4 className="font-black text-indigo-700 text-lg border-r-4 border-indigo-600 pr-3">بيانات المدرسة</h4>
                                <input type="text" placeholder="مكتب التربية بـ" value={meta.office} onChange={e => setMeta({...meta, office: e.target.value})} className="w-full p-4 border-2 border-gray-100 rounded-2xl focus:border-indigo-500 outline-none font-bold" />
                                <input type="text" placeholder="مديرية" value={meta.district} onChange={e => setMeta({...meta, district: e.target.value})} className="w-full p-4 border-2 border-gray-100 rounded-2xl focus:border-indigo-500 outline-none font-bold" />
                                <input type="text" placeholder="اسم المدرسة" value={meta.school} onChange={e => setMeta({...meta, school: e.target.value})} className="w-full p-4 border-2 border-gray-100 rounded-2xl focus:border-indigo-500 outline-none font-bold" />
                            </div>
                            <div className="space-y-4">
                                <h4 className="font-black text-indigo-700 text-lg border-r-4 border-indigo-600 pr-3">بيانات المقرر</h4>
                                <input type="text" placeholder="المادة" value={meta.subject} onChange={e => setMeta({...meta, subject: e.target.value})} className="w-full p-4 border-2 border-gray-100 rounded-2xl focus:border-indigo-500 outline-none font-bold" />
                                <input type="text" placeholder="الصف" value={meta.grade} onChange={e => setMeta({...meta, grade: e.target.value})} className="w-full p-4 border-2 border-gray-100 rounded-2xl focus:border-indigo-500 outline-none font-bold" />
                                <input type="text" placeholder="العام الدراسي" value={meta.year} onChange={e => setMeta({...meta, year: e.target.value})} className="w-full p-4 border-2 border-gray-100 rounded-2xl focus:border-indigo-500 outline-none font-bold" />
                            </div>
                            <div className="space-y-4">
                                <h4 className="font-black text-indigo-700 text-lg border-r-4 border-indigo-600 pr-3">التواريخ والاعتمادات</h4>
                                <input type="text" placeholder="اسم المعلم" value={meta.teacherName} onChange={e => setMeta({...meta, teacherName: e.target.value})} className="w-full p-4 border-2 border-gray-100 rounded-2xl focus:border-indigo-500 outline-none font-bold" />
                                <div className="p-4 bg-indigo-50 rounded-2xl border-2 border-indigo-100">
                                    <label className="block text-sm font-black text-indigo-800 mb-2">تاريخ بداية الخطة (ميلادي):</label>
                                    <input type="date" value={meta.startDate} onChange={e => setMeta({...meta, startDate: e.target.value})} className="w-full bg-transparent font-black outline-none text-indigo-900" />
                                    <p className="text-[10px] text-indigo-400 mt-2">سيتم تحويل التاريخ للهجري تلقائياً مع مراعاة أيام الإجازة.</p>
                                </div>
                            </div>
                        </div>

                        <div className="mb-10">
                            <h4 className="font-black text-gray-800 mb-6 flex items-center gap-3 text-xl">
                                <i className="fas fa-tasks text-indigo-600"></i> عناوين الدروس المقررة
                            </h4>
                            <div className="space-y-4 bg-gray-50 p-6 rounded-3xl shadow-inner max-h-72 overflow-y-auto">
                                {wizardLessons.map((l, i) => (
                                    <div key={i} className="flex gap-4 items-center bg-white p-4 rounded-2xl border border-gray-200 shadow-sm transition-all hover:shadow-md">
                                        <span className="text-indigo-600 font-black w-10 text-xl">{i+1}</span>
                                        <input type="text" placeholder="اكتب هنا عنوان الدرس..." value={l.title} onChange={e => updateWizardLesson(i, 'title', e.target.value)} className="flex-grow p-2 outline-none text-black font-bold text-lg" />
                                        <div className="flex items-center gap-3 border-r pr-5">
                                            <span className="text-xs text-gray-400 font-bold">الحصص:</span>
                                            <input type="number" min="1" value={l.count} onChange={e => updateWizardLesson(i, 'count', e.target.value)} className="w-16 text-center font-black text-indigo-600 text-xl bg-indigo-50 rounded-lg p-1" />
                                        </div>
                                        {i === wizardLessons.length - 1 && i > 0 && (
                                            <button onClick={() => removeWizardLesson(i)} className="text-red-400 hover:text-red-600 p-2 text-xl"><i className="fas fa-trash-alt"></i></button>
                                        )}
                                    </div>
                                ))}
                            </div>
                        </div>

                        <button onClick={handleBulkGenerate} className="w-full bg-indigo-600 text-white py-6 rounded-3xl font-black text-3xl shadow-2xl hover:bg-indigo-700 transition-all transform active:scale-95">
                            إنشاء الخطة الفصلية إلكترونياً
