                                                <td className="border border-black p-2 leading-tight text-center"><div contentEditable onBlur={e => handleRowChange(row.id, 'teachingMethods', e.currentTarget.innerText)} className="min-h-[45px] outline-none whitespace-pre-wrap break-words text-[12pt] text-black" dangerouslySetInnerHTML={{__html: row.teachingMethods}}></div></td>
