                                                <td className="border border-black p-2 leading-tight text-center"><div contentEditable onBlur={e => handleRowChange(row.id, 'values', e.currentTarget.innerText)} className="min-h-[45px] outline-none whitespace-pre-wrap break-words text-[12pt] text-black" dangerouslySetInnerHTML={{__html: row.values}}></div></td>
                                                <td className="border border-black p-2 leading-tight text-center"><div contentEditable onBlur={e => handleRowChange(row.id, 'evaluation', e.currentTarget.innerText)} className="min-h-[45px] outline-none whitespace-pre-wrap break-words text-[12pt] text-black" dangerouslySetInnerHTML={{__html: row.evaluation}}></div></td>
                                                <td className="border border-black p-2 leading-tight"><div contentEditable onBlur={e => handleRowChange(row.id, 'notes', e.currentTarget.innerText)} className="min-h-[45px] outline-none whitespace-pre-wrap break-words text-[12pt] text-black" dangerouslySetInnerHTML={{__html: row.notes}}></div></td>
                                            </tr>
                                        ))}
                                        {/* Dynamic Filler Rows */}
                                        {pageRows.length < ROWS_PER_PAGE && Array.from({length: ROWS_PER_PAGE - pageRows.length}).map((_, i) => (
                                            <tr key={i} className="h-16"><td colSpan={12} className="border border-black bg-gray-50/10"></td></tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>

                            {/* Signature Section - Black 13pt */}
                            <div className="mt-10 grid grid-cols-3 gap-12 text-center font-black text-[13pt] border-t-2 border-black pt-6 text-black">
