            </div>

            <div className="fixed bottom-8 right-8 no-print max-w-sm p-6 bg-gradient-to-br from-black to-gray-800 text-white rounded-[2rem] shadow-2xl animate-bounce border-2 border-white/20">
                <p className="text-sm font-black text-center leading-relaxed">
