export default SemesterPlanner;

import React, { useState, useRef, useEffect } from 'react';
import ToolHeader from '../ToolHeader';
import { generateBulkSemesterContent } from '../../services/geminiService';
import ActionButtons from '../ActionButtons';

// Declare libraries for PDF and Canvas
declare const jspdf: any;
declare const html2canvas: any;

interface SemesterRow {
    id: string;
    hijriDate: string;
    gregorianDate: string;
    periodCount: string;
    lessonTitle: string;
    objectives: string;
    teachingMethods: string;
    educationalAids: string;
    activitiesIn: string;
    activitiesOut: string;
    values: string;
    evaluation: string;
    notes: string;
}

interface HeaderMeta {
    ministry: string;
    office: string;
    district: string;
    school: string;
    subject: string;
    grade: string;
    semester: string;
    year: string;
    startDate: string;
    teacherName: string;
    supervisorName: string;
    schoolAdminName: string;
}

// Optimized rows count for A4 Landscape with 13pt font to avoid page overflow
const ROWS_PER_PAGE = 7; 

const SemesterPlanner: React.FC<{ onBack: () => void }> = ({ onBack }) => {
    // --- State Management ---
    const [rows, setRows] = useState<SemesterRow[]>([]);
    const [meta, setMeta] = useState<HeaderMeta>({
        ministry: 'وزارة التربية والتعليم والبحث العلمي',
        office: 'مكتب التربية والتعليم بـ',
        district: 'مكتب التربية والتعليم بمديرية',
        school: 'مدرسة',
        subject: 'اللغة العربية',
        grade: 'الثالث الثانوي',
        semester: 'الثاني',
        year: '1447',
        startDate: '2026-01-01',
        teacherName: '',
        supervisorName: '',
        schoolAdminName: ''
    });

    const [wizardLessons, setWizardLessons] = useState<{title: string, count: string}[]>([{title: '', count: '1'}]);
    const [showWizard, setShowWizard] = useState(false);
    const [isBulkGenerating, setIsBulkGenerating] = useState(false);
    const [isExporting, setIsExporting] = useState(false);

    const [secondaryLogo, setSecondaryLogo] = useState<string | null>(null);
    const [eagleImage, setEagleImage] = useState<string>('https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Emblem_of_Yemen.svg/200px-Emblem_of_Yemen.svg.png');

    const secondaryLogoRef = useRef<HTMLInputElement>(null);
    const eagleInputRef = useRef<HTMLInputElement>(null);

    // --- Hijri Logic (Precision) ---
    const getHijriDate = (gDate: string) => {
        if(!gDate) return '';
        try {
            const date = new Date(gDate);
            const formatter = new Intl.DateTimeFormat('ar-SA-u-ca-islamic-uma', {
                day: 'numeric',
                month: 'long',
                year: 'numeric'
            });
            const parts = formatter.formatToParts(date);
            const day = parts.find(p => p.type === 'day')?.value;
            const month = parts.find(p => p.type === 'month')?.value;
            const year = parts.find(p => p.type === 'year')?.value;
            // Expected format: 12/ رجب/ 1447هـ
            return `${day}/ ${month}/ ${year}هـ`;
        } catch(e) { return ''; }
    };

    const createEmptyRow = (): SemesterRow => ({
        id: Math.random().toString(36).substr(2, 9),
        hijriDate: '', gregorianDate: '', periodCount: '1', lessonTitle: '',
        objectives: '', teachingMethods: '', educationalAids: '', activitiesIn: '', activitiesOut: '', values: '', evaluation: '', notes: ''
    });

    // --- Handlers ---
    const handleBulkGenerate = async () => {
        const validLessons = wizardLessons.filter(l => l.title.trim() !== '');
        if (validLessons.length === 0) { alert('يرجى إدخال عناوين الدروس'); return; }

        setIsBulkGenerating(true);
        setShowWizard(false);

        try {
            const aiData = await generateBulkSemesterContent(validLessons, meta.subject);
            let currentDate = new Date(meta.startDate);
            const finalRows: SemesterRow[] = validLessons.map((l, idx) => {
                // Skip Yemen weekends (Friday/Saturday or just Friday depending on specific school)
                // Defaulting to Sat-Wed as work days
                while (currentDate.getDay() === 4 || currentDate.getDay() === 5) { 
                    currentDate.setDate(currentDate.getDate() + 1);
                }
                const gStr = currentDate.toISOString().split('T')[0];
                const hStr = getHijriDate(gStr);
                const lessonAi = aiData[idx] || {};
                currentDate.setDate(currentDate.getDate() + 1);

                return {
                    id: Math.random().toString(36).substr(2, 9),
                    gregorianDate: gStr,
                    hijriDate: hStr,
                    periodCount: l.count,
                    lessonTitle: l.title,
                    objectives: lessonAi.objectives || '',
                    teachingMethods: lessonAi.methods || '',
                    educationalAids: lessonAi.aids || '',
                    activitiesIn: lessonAi.activitiesIn || '',
                    activitiesOut: lessonAi.activitiesOut || '',
                    values: lessonAi.values || '',
                    evaluation: lessonAi.evaluation || '',
                    notes: ''
                };
            });
            setRows(finalRows);
        } catch (e) {
            alert('حدث خطأ في التوليد التلقائي');
        } finally {
            setIsBulkGenerating(false);
        }
    };

    const handleExportPDF = async () => {
        setIsExporting(true);
        const pdf = new jspdf.jsPDF({
            orientation: 'landscape',
            unit: 'mm',
            format: 'a4'
        });

        const pages = document.querySelectorAll('.semester-plan-page');

        try {
            await document.fonts.ready;

            for (let i = 0; i < pages.length; i++) {
                const pageElement = pages[i] as HTMLElement;

                // Fix visual stretching by defining a static capture resolution
                const canvas = await html2canvas(pageElement, {
                    scale: 4, // Ultra-high resolution
                    useCORS: true,
                    backgroundColor: '#ffffff',
                    width: 1123, // Fixed A4 Landscape pixel width (297mm at 96dpi)
                    height: 794,  // Fixed A4 Landscape pixel height (210mm at 96dpi)
                    onclone: (clonedDoc) => {
                        // Ensure all elements in clone are visible and black
                        const allText = clonedDoc.querySelectorAll('*');
                        allText.forEach((el: any) => {
                            if (el.style) {
                                el.style.color = '#000000';
                                el.style.borderColor = '#000000';
                            }
                        });
                    }
                });

                const imgData = canvas.toDataURL('image/jpeg', 1.0);
                if (i > 0) pdf.addPage();
                pdf.addImage(imgData, 'JPEG', 0, 0, 297, 210, undefined, 'FAST');
            }
            pdf.save(`خطة_توزيع_المقرر_${meta.subject}.pdf`);
        } catch (e) {
            console.error(e);
            alert("خطأ أثناء التصدير.");
        } finally {
            setIsExporting(false);
        }
    };

    const paginatedRows = [];
    for (let i = 0; i < rows.length; i += ROWS_PER_PAGE) {
        paginatedRows.push(rows.slice(i, i + ROWS_PER_PAGE));
    }
    if (paginatedRows.length === 0) paginatedRows.push([]);

    return (
        <div className="pb-20">
            <ToolHeader title="خطة توزيع المنهج الاحترافية" onBack={onBack} />

            {/* Control Bar */}
            <div className="no-print neumorphic-outset p-6 mb-8 flex flex-wrap gap-4 items-center justify-center sticky top-20 z-40 bg-white/95 backdrop-blur-md">
                <button onClick={() => setShowWizard(true)} className="bg-blue-600 text-white px-8 py-3 rounded-2xl font-black hover:scale-105 shadow-lg flex items-center gap-2">
                    <i className="fas fa-magic"></i> معالج البيانات
                </button>
                <button onClick={() => setRows([...rows, createEmptyRow()])} className="bg-green-600 text-white px-8 py-3 rounded-2xl font-black hover:scale-105 shadow-lg">
                    <i className="fas fa-plus ml-2"></i> إضافة يدوي
                </button>
                <button onClick={handleExportPDF} disabled={isExporting || rows.length === 0} className="bg-black text-white px-8 py-3 rounded-2xl font-black hover:scale-105 shadow-lg disabled:opacity-50">
                    {isExporting ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-file-pdf"></i>} تصدير PDF بجودة عالية
                </button>
            </div>

            {/* Wizard Modal */}
            {showWizard && (
                <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm overflow-y-auto">
                    <div className="bg-white rounded-3xl shadow-2xl w-full max-w-4xl p-8 max-h-[90vh] overflow-y-auto border-4 border-blue-100">
                        <h3 className="text-3xl font-black text-blue-900 mb-8 text-center border-b pb-4">إعداد خطة المنهج</h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                            <div className="space-y-4">
                                <input type="text" placeholder="المدرسة" value={meta.school} onChange={e => setMeta({...meta, school: e.target.value})} className="w-full p-4 border-2 border-gray-100 rounded-xl font-bold text-black" />
                                <input type="text" placeholder="المادة" value={meta.subject} onChange={e => setMeta({...meta, subject: e.target.value})} className="w-full p-4 border-2 border-gray-100 rounded-xl font-bold text-black" />
                                <input type="text" placeholder="العام الدراسي" value={meta.year} onChange={e => setMeta({...meta, year: e.target.value})} className="w-full p-4 border-2 border-gray-100 rounded-xl font-bold text-black" />
                            </div>
                            <div className="space-y-4">
                                <input type="text" placeholder="المعلم" value={meta.teacherName} onChange={e => setMeta({...meta, teacherName: e.target.value})} className="w-full p-4 border-2 border-gray-100 rounded-xl font-bold text-black" />
                                <div className="p-4 bg-blue-50 rounded-xl border border-blue-100">
