                        <h4 className="font-black text-gray-800 mb-4"><i className="fas fa-list-ol ml-2"></i> عناوين الدروس المقررة:</h4>
                        <div className="space-y-2 mb-8 max-h-60 overflow-y-auto bg-gray-50 p-4 rounded-xl">
                            {wizardLessons.map((l, i) => (
