                                    <input type="number" value={l.count} onChange={e => { const nl = [...wizardLessons]; nl[i].count = e.target.value; setWizardLessons(nl); }} className="w-12 text-center border rounded font-bold text-black" />
                                </div>
                            ))}
                        </div>
                        <div className="flex gap-4">
                            <button onClick={handleBulkGenerate} className="flex-1 bg-blue-700 text-white py-4 rounded-2xl font-black text-xl hover:bg-blue-800 transition-all shadow-xl">بدء الإنشاء الذكي</button>
                            <button onClick={() => setShowWizard(false)} className="px-8 py-4 bg-gray-200 text-gray-700 rounded-2xl font-bold">إلغاء</button>
                        </div>
