    'المقالية', 'الإيجاز (قصيرة)', 'تصنيف المجموعات', 'اختبار الأداء', 'أسئلة الرسم البياني',
    'حل المشكلات', 'أسئلة التكميل', 'الأسئلة التشخيصية', 'الأسئلة الاستنباطية',
