                                            <th className="border border-black p-3" rowSpan={2}>أساليب التقويم</th>
                                            <th className="border border-black p-3 w-[90px]" rowSpan={2}>ملحوظات</th>
                                        </tr>
                                        <tr className="bg-gray-50 font-black text-[10pt]">
                                            <th className="border border-black p-2 w-[60px]">هجري</th>
                                            <th className="border border-black p-2 w-[60px]">ميلادي</th>
                                            <th className="border border-black p-2 w-[65px]">الصفية</th>
                                            <th className="border border-black p-2 w-[65px]">اللاصفية</th>
